	["#490109", "#d40011", "#fd7495", "#5e4ef8", "#14029a"],
	["#8f704b", "#daae6d", "#89e3f6", "#4d9e9b", "#44786a"],
	["#fff69f", "#fdd870", "#d0902f", "#a15501", "#351409"]
]
var palette;

function setup() {
  createCanvas(innerWidth, innerHeight);
	frameRate(60)
	palette = random(palettes).map((e) => e + "80");
  frameRate(30);
  loop();
}

function draw() {
	if (frameCount % 300 === 0) setup(); // 5 sec
  const S = max(width, height)
  const D = S / C;
  background("lightgray");
  // translate((noise(12.3+frameCount*0.0234)-0.5)*D*2, (noise(23.1+frameCount*0.0341)-0.5)*D*2)
  strokeWeight(D / 2);
  for (let y = D; y < height; y += D) {
    for (let x = D; x < width; x += D) {
      stroke(arr_noise(palette, x*x-y));
      point(x, y);
      if (noise(252345.23 + frameCount * 0.00142 + x + y * 1.34) < 0.4) {
        stroke(arr_noise(palette, x+y*y));
        const xf = noise(245.231 + frameCount * 0.0008142 + x + y * 1.34) < 0.5 ? -1 : 1;
        const yf = noise(1345.123 + frameCount * 0.0009142 + x * 1.34 + y) < 0.5 ? -1 : 1;
        mline(x, y, x + xf * D, y + yf * D);
      }
    }
  }
}

function mline(x1, y1, x2, y2) {
  if (x1 === 0 || y1 === 0 || x2 === 0 || y2 === 0) return;
  if (x1 >= width || x2 >= width) return;
  if (y1 >= height || y2 >= height) return;
  line(x1, y1, x2, y2);
}

function arr_noise(arr, magicNum) {
  const n = noise(magicNum + frameCount * 0.001234);
  const i = ~~(n * arr.length);
  return arr[i];
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
